        [...h.files.values()].filter((file) => file.extension === "md"),
      ).toHaveLength(2);
      expect(
        Object.values((await loadRelations(h.plugin)).relations)[0]
          ?.destination,
      ).toBe(local ? "source" : sourceRid);
      expect(
        h.requests.filter((request) => request.table === "my_contents"),
      ).toHaveLength(1);
    },
