import getPageTitleByPageUid from "roamjs-components/queries/getPageTitleByPageUid";
import { readImportedSourceIdentity } from "./importedSourceIdentity";
import internalError from "./internalError";
import { getErrorMessage } from "./getErrorMessage";
import { materializeSharedNode } from "./materializeSharedNode";
import { resolveSharedNodeTypes } from "./resolveSharedNodeTypes";
import { getLoggedInClient } from "./supabaseContext";

export const REFRESH_ERROR_TYPE = "Imported node refresh failed";
const REFRESH_ERROR_OPERATION = "refresh-imported-node";

type RefreshImportedNodeResult = {
  status: "refreshed" | "skipped" | "failed";
  message: string;
  warning?: string;
};

export const refreshImportedNode = async ({
  pageUid,
  force,
}: {
  pageUid: string;
  force: boolean;
}): Promise<RefreshImportedNodeResult> => {
  try {
    const title = getPageTitleByPageUid(pageUid);
    const identity = readImportedSourceIdentity(pageUid);
    if (!identity)
      return {
        status: "failed",
        message: `"${title}" has no stored source identity, so it cannot be refreshed.`,
      };

    const client = await getLoggedInClient();
    if (!client)
      return {
        status: "failed",
        message: "Could not connect to shared persistence.",
      };

    const sharedNode = await getSharedNodeByRid({
      client,
      rid: identity.sourceNodeRid,
    });
    if (!sharedNode)
      return {
        status: "failed",
        message: `The source of "${title}" is no longer shared with your groups, so it cannot be refreshed.`,
      };

    const nodeTypesBySchemaId = await resolveSharedNodeTypes({
      client,
      sharedNodes: [sharedNode],
    });
    const result = await materializeSharedNode({
      client,
      sharedNode,
      nodeType: nodeTypesBySchemaId.get(sharedNode.schemaId),
      force,
    });
    if (!result.success) {
      internalError({
        error: new Error(result.error.message),
        type: REFRESH_ERROR_TYPE,
        context: {
          operation: REFRESH_ERROR_OPERATION,
          pageUid,
          stage: result.error.stage,
        },
        sendEmail: false,
      });
      return { status: "failed", message: result.error.message };
    }
    if (result.pageUid !== pageUid)
      return {
        status: "failed",
        message: `A different page ("${getPageTitleByPageUid(result.pageUid)}") is linked to the same source and was refreshed instead.`,
      };
    if (result.action === "skipped")
      return {
        status: "skipped",
        message: `"${sharedNode.title}" is already up to date.`,
      };
    return {
      status: "refreshed",
      message: `Refreshed "${sharedNode.title}" from ${sharedNode.spaceName}.`,
      ...(result.warning ? { warning: result.warning } : {}),
    };
  } catch (error) {
    internalError({
      error,
      type: REFRESH_ERROR_TYPE,
      context: { operation: REFRESH_ERROR_OPERATION, pageUid },
      sendEmail: false,
    });
    return {
      status: "failed",
      message: `Could not refresh this page: ${getErrorMessage(error)}`,
    };
  }
};
 * Refresh a single imported file by fetching the latest content from the database
 * Reuses the same logic as importSelectedNodes by treating it as a single-node import
 */
export const refreshImportedFile = async ({
  plugin,
  file,
  client,
}: {
  plugin: DiscourseGraphPlugin;
  file: TFile;
  client?: DGSupabaseClient;
}): Promise<{ success: boolean; error?: string }> => {
  const supabaseClient = client || (await getLoggedInClient(plugin));
  if (!supabaseClient) {
    throw new Error("Cannot get Supabase client");
  }
  const cache = plugin.app.metadataCache.getFileCache(file);
  const frontmatter = cache?.frontmatter as Record<string, unknown> | undefined;
  if (!frontmatter?.importedFromRid || !frontmatter?.nodeInstanceId) {
    return {
      success: false,
      error: "Missing frontmatter: importedFromRid or nodeInstanceId",
    };
  }
  if (
    typeof frontmatter.importedFromRid !== "string" ||
    typeof frontmatter.nodeInstanceId !== "string"
  ) {
    return {
      success: false,
      error: "Non-string frontmatter: importedFromRid or nodeInstanceId",
    };
  }
  const { spaceName, spaceId } = await getSpaceNameIdFromRid(
    supabaseClient,
    frontmatter.importedFromRid,
  );
  if (spaceId === -1) {
    return { success: false, error: "Could not get the space Id" };
  }
  const metadataResp = await supabaseClient
    .from("Content")
    .select("metadata")
    .eq("space_id", spaceId)
    .eq("source_local_id", frontmatter.nodeInstanceId)
    .eq("variant", "direct")
    .maybeSingle();
  const metadata = metadataResp.data?.metadata;
  const filePath: string | undefined =
    typeof metadata === "object" &&
    typeof (metadata as Record<string, unknown>).filePath === "string"
      ? ((metadata as Record<string, unknown>).filePath as string)
      : undefined;
  const result = await importSelectedNodes({
    plugin,
    selectedNodes: [
      {
        nodeInstanceId: frontmatter.nodeInstanceId,
        title: file.basename,
        spaceId,
        spaceName,
        filePath,
        groupId:
          (frontmatter.publishedToGroups as string[] | undefined)?.[0] ?? "",
        selected: false,
      },
    ],
  });
  return {
    success: result.success > 0,
    error: result.failed > 0 ? "Failed to refresh imported file" : undefined,
  };
};

