    spaceUri: sourceSpaceUri,
    localId: sourceNodeTypeId,
  });

  const newNodeType: DiscourseNode = {
    id: sourceNodeTypeId,
    name: parsed.name,
    format: parsed.format,
    color: parsed.color,
    tag: parsed.tag,
    template: parsed.template,
    keyImage: parsed.keyImage,
    created: now,
    modified: now,
    authorId: schemaData.author_id ?? undefined,
