    typeof row.filepath === "string" && typeof row.filehash === "string"
      ? [
          {
            filepath: row.filepath,
            filehash: row.filehash,
            source_path:
              typeof row.source_path === "string" ? row.source_path : null,
          },
        ]
      : [],
