{"id": "PUB-05", "area": "PUB", "title": "Imported node offers no way to publish (Roam)", "dirs": ["RR", "OR"], "steps": "On an imported page, check the title shows Refresh and no Publish. Then run “DG: Share current node”. Then open a query or canvas “Share Data” dialog whose results include the imported page and use the Publish tab.", "expected": "No path publishes an imported node.", "src": "ENG-2294 (intent; Done When names only the button)", "rating": "risk", "why": "Only the title button is gated. The command and the Export dialog's Publish tab check only that the page is a discourse node, so the imported copy can be published and would show up in other spaces as a duplicate. This is the behavior ENG-2294 was filed for.", "ev": ["apps/roam/src/utils/registerCommandPaletteCommands.ts:284-290", "apps/roam/src/components/Export.tsx:248-251", "apps/roam/src/utils/initializeObserversAndListeners.ts:134"], "method": "bash", "evidence": "shot", "pri": "P0"}
{"id": "PUB-07", "area": "PUB", "title": "Publish query results with mixed rows", "dirs": ["RR", "RO"], "steps": "In a query block, open Share Data, then Publish, with discourse and non-discourse results and some nodes that never synced.", "expected": "Only discourse nodes publish, and the toast gives a clear success and failure count.", "src": "ENG-1890", "rating": "risk", "why": "A publish that grants nothing reads like success (“Published 0 nodes… N not synced yet”), noted on ENG-1890 with no follow-up. Relation and node-type failures are not counted.", "ev": ["apps/roam/src/components/Export.tsx:882-885, 900-908"], "method": "bash", "evidence": "shot", "pri": "P2"}
{"id": "PUB-09", "area": "PUB", "title": "Publish a note you just converted (Obsidian)", "dirs": ["OR", "OO"], "steps": "Run “Convert current page to discourse node”, then publish right away without editing.", "expected": "Publish works.", "src": "Obsidian reference flow", "rating": "risk", "why": "The node id is written only by sync, so publish says “Please sync the node first” until the next edit or full sync.", "ev": ["apps/obsidian/src/utils/fileChangeListener.ts:176-177", "apps/obsidian/src/utils/createNode.ts:212-217"], "method": "bash", "evidence": "shot", "pri": "P1"}
{"id": "PUB-10", "area": "PUB", "title": "Turn on sync mode without reloading (Obsidian)", "dirs": ["OR", "OO"], "steps": "Turn on “(BETA) Sync mode enable” in the Admin panel (Ctrl/Cmd+Shift+A in the plugin settings). Without reloading, publish a note and then edit it.", "expected": "The edit syncs after about 5 s.", "src": "Not specified", "rating": "risk", "why": "The file listener is created only when the plugin loads, so edits don't sync until a reload.", "ev": ["apps/obsidian/src/index.ts:97-113"], "method": "bash", "evidence": "receipt", "pri": "P2"}
{"id": "DSC-10", "area": "DSC", "title": "Node whose node type isn't visible", "dirs": ["RR", "RO", "OR", "OO"], "steps": "Share a node whose node-type grant is missing (for example after a failed schema publish), then import it.", "expected": "A clear error, or the node imports with its type.", "src": "ENG-2098, ENG-1877", "rating": "risk", "why": "Roam imports it with an undecorated title and no warning. Obsidian shows “Unknown node type” for Obsidian-origin nodes and fails silently (console only) for Roam-origin nodes.", "ev": ["apps/roam/src/utils/resolveSharedNodeTypes.ts:75-83", "apps/obsidian/src/utils/importNodes.ts:1242-1244, 1699-1713"], "method": "bash", "evidence": "log", "pri": "P2", "iso": true}
{"id": "TXT-02", "area": "TXT", "title": "Rich Roam page into Obsidian", "dirs": ["RO"], "steps": "Import the Roam fixture page into a vault.", "expected": "Readable markdown with correct block boundaries.", "src": "Last bug bash, UC3", "rating": "risk", "why": "The last bug bash saw wrong block boundaries on “[[EVD]] - image - [[@uhm]]”. Obsidian converts only links, so #[[tag]] becomes #[[tag|tag]], and ^^highlight^^, key:: value and {{[[pdf]]: url}} stay as written.", "ev": ["apps/obsidian/src/utils/importNodes.ts:672-761, 690-693"], "method": "bash", "evidence": "shot", "pri": "P0"}
{"id": "TTL-04", "area": "TTL", "title": "Roam node type template reaches Obsidian", "dirs": ["RO"], "steps": "Give a Roam node type a template. Import a node of that type into a vault without the type.", "expected": "The template arrives with the type, as it does from Obsidian.", "src": "ENG-2202", "rating": "risk", "why": "Obsidian creates a template only when the schema has both a template name and a body. Roam schemas carry only the body after PR #1475, so the template is dropped.", "ev": ["apps/obsidian/src/utils/importNodes.ts:1283-1306", "apps/roam/src/utils/conceptConversion.ts:68-80"], "method": "bash", "evidence": "shot", "pri": "P2"}
{"id": "TTL-06", "area": "TTL", "title": "Type names that differ only by case", "dirs": ["RR", "RO", "OR", "OO"], "steps": "Source type “Claim”, destination type “claim”. Import a node, then a relation that uses the type.", "expected": "One consistent match.", "src": "Not specified", "rating": "risk", "why": "Obsidian and Roam's relation import match names case-insensitively; Roam's node import matches case-sensitively, so a second type can be created.", "ev": ["apps/roam/src/utils/resolveSharedNodeTypes.ts:34-43", "apps/roam/src/utils/importSharedRelations.ts:32-79"], "method": "bash", "evidence": "shot", "pri": "P2"}
