190:     const schemaRid = spaceUriAndLocalIdToRid(spaceUri, relationType, "schema");
191:     const relationBlockUid = schemaRidToLocalId[schemaRid];
192:     if (relationBlockUid === undefined)
193:       throw new Error(`Missing relation type: ${relationType}`);
194:     const sourceUid = await findTargetUid(source, spaceUri);
195:     if (sourceUid === null)
196:       throw new Error(`Missing relation source: ${source}`);
197:     const destinationUid = await findTargetUid(destination, spaceUri);
198:     if (destinationUid === null)
199:       throw new Error(`Missing relation destination: ${destination}`);
200:     if (existing.has(sourceNodeRid)) {
201:       // Update existing
202:       const existingRelUid =
203:         await findImportedNodeUidBySourceRid(sourceNodeRid);
204:       if (existingRelUid === null)
205:         throw new Error("Could not get imported block");
206:       const existingRel = allRelations.find(
207:         (r) => r.relationId === existingRelUid,
208:       );
209:       if (existingRel === undefined) throw new Error("Could not find relation");
210:       if (
211:         existingRel.hasSchema === relationBlockUid &&
212:         existingRel.sourceUid === sourceUid &&
213:         existingRel.destinationUid === destinationUid
214:       )
215:         continue;
216:       // It was imported and modified. We could update, but easier to delete and recreate.
217:       await deleteBlock(existingRelUid);
