347:  * Resolve an endpoint id (RID or legacy nodeInstanceId) to a file in this vault.
348:  * Handles: imported nodes (frontmatter.importedFromRid), local nodes by RID (parse RID, match spaceUri to local, find by nodeInstanceId), and legacy nodeInstanceId.
349:  */
350: export const resolveEndpointToFile = (
351:   plugin: DiscourseGraphPlugin,
352:   endpointId: string,
353:   endpointToFileMap?: Map<string, TFile>,
354: ): TFile | null => {
355:   if (endpointToFileMap) {
356:     const cached = endpointToFileMap.get(endpointId);
357:     if (cached) return cached;
358:   }
359: 
360:   if (looksLikeRid(endpointId)) {
361:     const byImported = getFileForImportedFromRid(plugin, endpointId);
362:     if (byImported) return byImported;
363:     const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(endpointId);
364:     if (spaceUri === getLocalSpaceUri(plugin.app)) {
365:       return resolveEndpointToFile(plugin, sourceLocalId, endpointToFileMap);
366:     }
367:     return null;
368:   }
369: 
370:   const queryEngine = new QueryEngine(plugin.app);
371:   return queryEngine.getFileByEndpoint(endpointId);
372: };
