377:  */
378: export const getFileForNodeInstanceId = (
379:   plugin: DiscourseGraphPlugin,
380:   nodeInstanceIdOrRid: string,
381: ): TFile | null => {
382:   return resolveEndpointToFile(plugin, nodeInstanceIdOrRid);
383: };
