385: export const getFileForNodeInstanceIds = (
386:   plugin: DiscourseGraphPlugin,
387:   nodeInstanceIdsOrRids: Set<string>,
388: ): Record<string, TFile> => {
389:   const result: Record<string, TFile> = {};
390:   if (nodeInstanceIdsOrRids.size == 0) return result;
391:   for (const idOrRid of nodeInstanceIdsOrRids) {
392:     const f = getFileForNodeInstanceId(plugin, idOrRid);
393:     if (f) result[idOrRid] = f;
394:   }
395:   return result;
396: };
