40: /**
41:  * Roam's own rule, verified against `file.upload`: it branches on the first part of the
42:  * type, and everything it does not recognise becomes a bare URL. Reproduced rather than
43:  * curated, so an imported asset renders like the same file uploaded directly, awkward
44:  * cases included (`image/vnd.adobe.photoshop` embeds, possibly as a broken image).
45:  *
46:  * Normalised first: the value comes from a `FileReference` row, so its case and
47:  * parameters are not ours to assume.
48:  */
49: const kindForMimetype = (
50:   mimetype: string | undefined,
51: ): AssetKind | undefined => {
52:   const [type, subtype] =
53:     mimetype?.toLowerCase().split(";")[0]?.trim().split("/") ?? [];
54:   if (type === "image") return "image";
55:   if (type === "audio") return "audio";
56:   if (type === "video") return "video";
57:   // Scoped to the one type verified above.
58:   if (type === "application" && subtype === "pdf") return "pdf";
59:   return undefined;
60: };
