91: const extensionOf = (path: string): string => {
92:   // A URL's query string is not part of its name: Roam storage URLs end in `?alt=media`.
93:   const leaf = path.split(/[?#]/)[0]?.split("/").pop() ?? "";
94:   const dot = leaf.lastIndexOf(".");
95:   return dot > 0 ? leaf.slice(dot + 1).toLowerCase() : "";
96: };
