98: /**
99:  * How the source markdown wrote the reference: `embed` is `![...]` in any of its
100:  * spellings, `link` is `[...]`, and a bare URL is neither.
101:  */
102: type ReferenceForm = "embed" | "link" | "bare";
103: 
104: /** How the reference was written, and what the source said it was, where it said so. */
105: type ReferenceContext = {
106:   form: ReferenceForm;
107:   /** From `{{[[pdf]]: url}}` and its bracket-less spelling, which name the type. */
108:   declaredKind?: AssetKind;
109:   /**
110:    * What followed the pipe in `![[locator|…]]`. A width on an image and a label on
