122: const kindOf = (
123:   { sourcePath, sourceLocator, mimetype }: ResolvedAsset,
124:   { form, declaredKind }: ReferenceContext,
125: ): AssetKind => {
126:   const byType = kindForMimetype(mimetype);
127:   if (byType) return byType;
128: 
129:   if (declaredKind) return declaredKind;
130: 
131:   const named =
132:     kindForExtension(extensionOf(sourcePath ?? "")) ??
133:     kindForExtension(extensionOf(sourceLocator));
134:   if (named) return named;
135: 
136:   // Only where nothing names an extension: an embed of `report.docx` said "embed", never
137:   // "image", so treating it as one would drop the filename `labelFor` exists to show.
138:   const unnamed = !extensionOf(sourcePath ?? "") && !extensionOf(sourceLocator);
