160:   asset,
161:   linkText,
162: }: {
163:   asset: ResolvedAsset;
164:   linkText: string;
165: }): string => {
166:   const trimmed = linkText.trim();
167:   if (trimmed) return trimmed;
168:   // `||`, not `??`: an empty recorded name is no name, and falling through to the locator
169:   // is what the chain is for. With `??` the label would come out as the storage URL,
170:   // which is exactly what this function exists to avoid.
171:   const leaf = (asset.sourcePath || asset.sourceLocator).split(/[?#]/)[0] ?? "";
