49: const kindForMimetype = (
50:   mimetype: string | undefined,
51: ): AssetKind | undefined => {
52:   const [type, subtype] =
53:     mimetype?.toLowerCase().split(";")[0]?.trim().split("/") ?? [];
54:   if (type === "image") return "image";
55:   if (type === "audio") return "audio";
56:   if (type === "video") return "video";
