62: /**
63:  * Extension to kind, indexed from `mime-db` rather than maintained here.
64:  *
65:  * Several types can claim one extension (`.mp4` is both `application/mp4` and
66:  * `video/mp4`) and `mime-db` states no preference. A non-rendering type never wins; where
67:  * two rendering types claim an extension the first indexed wins, costing the wrong player
68:  * rather than a broken link.
69:  *
70:  * Prototype-free and read through `Object.hasOwn`: a locator ending in `.constructor`
71:  * would otherwise resolve to a function and write `undefined` into the user's page.
72:  */
73: const EXTENSION_KINDS: Record<string, AssetKind> = Object.entries(
74:   mimeDb,
75: ).reduce(
76:   (map, [mimetype, definition]) => {
77:     const kind = kindForMimetype(mimetype);
78:     if (kind === undefined) return map;
79:     for (const extension of definition.extensions ?? [])
