291:  *
292:  * Ordered. The media-embed branches precede the wikilink ones, or `{{[[pdf]]: url}}`, the
293:  * form Roam writes a stored PDF in, would be read as a page reference to `pdf`.
294:  *
295:  * The wikilink branches match Roam page references too, but those never resolve: a page
296:  * name is not a recorded locator.
297:  *
298:  * Every branch stops at a line break. Roam stores a page as blocks, so a reference spelled
299:  * across one could be rewritten here but never again from a single block's text, and the
300:  * two readings would disagree. One spelled that way is left as published instead, which is
301:  * what an asset with no row already gets.
302:  */
303: const LINK_PATTERN = new RegExp(
304:   [
305:     String.raw`!\[([^\]\n]*)\]\((<[^>\n]*>|[^)\s]+)(?:[^\S\n]+"[^"\n]*")?\)`, // ![alt](locator)
306:     // No `[` in the label, so the outer bracket of `[![alt](image)](link)` fails here and
307:     // the scan reaches the inner embed. Alternation is per position, so branch order
308:     // alone would not do it.
309:     String.raw`\[([^\]\[\n]*)\]\((<[^>\n]*>|[^)\s]+)(?:[^\S\n]+"[^"\n]*")?\)`, // [label](locator)
310:     // The keyword is captured, not discarded: for a storage uid with no extension it is
311:     // the only statement of the type.
312:     String.raw`\{\{\[\[(pdf|audio|video)\]\]:[^\S\n]*(${URL_PATTERN})[^\S\n]*\}\}`, // {{[[pdf]]: url}}
313:     String.raw`\{\{(pdf|audio|video):[^\S\n]*(${URL_PATTERN})[^\S\n]*\}\}`, // {{pdf: url}}
314:     // The pipe is a width on an image (`![[x.png|300]]`) and a label on anything else
315:     // (`![[a.pdf|the paper]]`), so it is captured and `render` decides once it has a kind.
316:     String.raw`!\[\[([^\]|\n]+)(?:\|([^\]\n]*))?\]\]`, // ![[locator]] or ![[locator|300]]
317:     String.raw`\[\[([^\]|\n]+)(?:\|([^\]\n]*))?\]\]`, // [[locator]] or [[locator|label]]
318:     // An autolink is matched whole so its brackets go away with the rest of the match.
319:     // Capturing only the URL would leave `<` and `>` around the rewritten link.
320:     `(<${URL_PATTERN}>|${URL_PATTERN})`, // a bare URL, rewritten only when a row matches it
321:   ].join("|"),
322:   "g",
323: );
410:     // A wikilink embed carries no separate text, so its label comes from the asset.
411:     linkText: imageLocator ? (imageAlt ?? "") : (linkLabel ?? wikiLabel ?? ""),
412:   };
413: };
