415: /**
416:  * Every locator this markdown refers an asset by, as `rewriteAssetLinks` reads them.
417:  * Widening these through `lookupCandidates` gives exactly the locators that would resolve,
418:  * so a caller deciding which references to act on cannot drift from the rewrite.
419:  */
420: export const collectAssetLocators = (markdown: string): string[] => {
421:   const locators: string[] = [];
422:   for (const match of markdown.matchAll(LINK_PATTERN)) {
423:     const [, ...groups] = match;
424:     const parsed = parseMatch(groups);
425:     if (parsed) locators.push(parsed.locator);
426:   }
427:   return locators;
428: };
429: 
430: export const rewriteAssetLinks = ({
431:   markdown,
432:   assets,
433:   unresolved = [],
434: }: {
435:   markdown: string;
436:   assets: ResolvedAsset[];
437:   unresolved?: UnresolvedAsset[];
438: }): string => {
439:   if (!assets.length && !unresolved.length) return markdown;
440:   const byLocator = new Map(
441:     assets.map((asset) => [asset.sourceLocator, asset]),
442:   );
443:   const unresolvedByLocator = new Map(
444:     unresolved.map((asset) => [asset.sourceLocator, asset]),
445:   );
446: 
447:   return markdown.replace(LINK_PATTERN, (match: string, ...args: unknown[]) => {
448:     const parsed = parseMatch(args as (string | undefined)[]);
449:     if (!parsed) return match;
450:     const { locator, form, declaredKind, embedAlias, linkText, isEncoded } =
451:       parsed;
452: 
453:     const context = { form, declaredKind, embedAlias };
454:     const candidates = lookupCandidates(locator);
455:     // A copy wins over a marker when two spellings match different rows.
456:     const matched =
457:       candidates.find((candidate) => byLocator.has(candidate)) ??
458:       candidates.find((candidate) => unresolvedByLocator.has(candidate));
459:     if (matched === undefined) return match;
460: 
461:     // Punctuation comes back only on a bare URL, where it was the sentence's. Inside
462:     // `![](…)` the locator is already delimited, so a trailing character belonged to
463:     // the URL and restoring it would leave a stray mark beside the embed.
464:     const trailing =
465:       form === "bare" && matched !== locator
466:         ? (locator.match(TRAILING_PUNCTUATION)?.[0] ?? "")
467:         : "";
468: 
469:     const asset = byLocator.get(matched);
470:     if (asset) return `${render({ asset, linkText, context })}${trailing}`;
471: 
472:     const unresolvedAsset = unresolvedByLocator.get(matched);
473:     if (!unresolvedAsset) return match;
474:     // A marked URL keeps its own text, so the sentence's punctuation is split off it
475:     // first. In an autolink it sits inside the brackets and stays there.
476:     const [reference, after] =
477:       trailing && match.endsWith(trailing)
478:         ? [match.slice(0, -trailing.length), trailing]
479:         : [match, ""];
480:     // The match offset is the only number `replace` passes.
481:     const offset = args.find((arg) => typeof arg === "number") as number;
482:     return `${renderMarked({
483:       marker: unresolvedAsset.marker,
484:       match: reference,
485:       // As spelled, not as recorded: the recorded form is decoded.
486:       locator,
487:       isEncoded,
488:       isInsideLinkLabel:
489:         match.startsWith("![") &&
490:         isInsideLinkLabel({
491:           markdown,
492:           start: offset,
493:           end: offset + match.length,
494:         }),

