CREATE OR REPLACE FUNCTION public.rid_or_local_id_to_concept_db_id(rid VARCHAR, default_space_id BIGINT)
RETURNS BIGINT STRICT STABLE
SET search_path = ''
LANGUAGE plpgsql AS $$
DECLARE r public.accessible_resource;
BEGIN
    r := (SELECT public.rid_to_space_id_and_local_id(rid));
    IF r.space_id IS NULL THEN
        RETURN  (SELECT id FROM public."Concept" WHERE space_id = default_space_id AND source_local_id = rid);
    ELSE
        RETURN (SELECT id FROM public."Concept" WHERE space_id = r.space_id AND source_local_id = r.source_local_id);
    END IF;
END;
$$;

CREATE TYPE public.concept_local_input AS (
    -- concept columns
    epistemic_status public."EpistemicStatus",
    name character varying,
    description text,
    author_id bigint,
    created timestamp without time zone,
    last_modified timestamp without time zone,
    space_id bigint,
    schema_id bigint,
    literal_content jsonb,
  groups.map((group) => ({
    ...group,
    isPublished: publishedToGroups.includes(group.id),
  }));

export const publishNodeToSelectedGroup = async ({
  plugin,
  file,
  frontmatter,
  groupId,
}: {
  plugin: DiscourseGraphPlugin;
  file: TFile;
  frontmatter: FrontMatterCache | Record<string, unknown>;
  groupId: string;
}): Promise<void> => {
  const publishedToGroups = getPublishedToGroups(frontmatter);
  if (publishedToGroups.includes(groupId)) {
    throw new Error("Already shared with this group");
  }

  if (!frontmatter.nodeInstanceId) {
    throw new Error("Please sync the node first");
  }

  await publishNode({
    plugin,
    file,
    frontmatter: frontmatter as FrontMatterCache,
    groupId,
  });
};

export const publishNodeToAllGroups = async ({
  plugin,
  file,
}: {
  plugin: DiscourseGraphPlugin;
  file: TFile;
}): Promise<number> => {
  const frontmatter = plugin.app.metadataCache.getFileCache(file)?.frontmatter;
  if (!frontmatter) {
    throw new Error("File metadata not available");
  }

  const client = await getLoggedInClient(plugin);
  if (!client) {
    throw new Error("Cannot connect to database");
  }

  const memberGroupIds = await getAvailableGroupIds(client);
  const existingPublish = getPublishedToGroups(frontmatter);
  const toPublish = memberGroupIds.filter(
    (groupId) => !existingPublish.includes(groupId),
  );

  if (toPublish.length === 0) {
    return 0;
  }

  if (!frontmatter.nodeInstanceId) {
    throw new Error("Please sync the node first");
  }

  await syncAllNodesAndRelations(plugin);

  for (const groupId of toPublish) {
    await publishNodeToGroup({
      plugin,
      file,
      frontmatter,
      myGroup: groupId,
      skipFrontmatterUpdate: true,
    });
   * Return all markdown pages under import/ that have importedFromRid and nodeInstanceId.
   * Uses DataCore when available; falls back to vault iteration otherwise.
   */
  getImportedNodePages = (): TFile[] => {
    const datacore = this.getReadyDatacore();
    if (datacore) {
      try {
        const dcQuery = `@page and path("import") and exists(importedFromRid) and exists(nodeInstanceId)`;
        const pages = datacore.query(dcQuery);
