    builder({
      absWorkingDir: process.cwd(),
      entryPoints: [path.join(srcRoot, entryTs)],
      outdir,
      bundle: true,
      format,
      sourcemap: isProd ? undefined : "inline",
      minify: isProd,
      entryNames: out,
      external: external,
      define: {
