                    .join("\n");
                }

                fs.writeFileSync(
                  outputStylesFile,
                  result.css + "\n" + additionalStyles,
                );
              } else if (fs.existsSync(stylesDir)) {
                const styleFiles = fs
                  .readdirSync(stylesDir)
                  .filter((file) => file.endsWith(".css"));
                const combinedStyles = styleFiles
                  .map((file) =>
