/**
 * Record a demo video of an already-running Electron app (Obsidian) over CDP.
 *
 * Unlike recordDemo.ts this does not launch a browser: start the app yourself
 * with remote debugging, e.g.
 *
 *   ~/Applications/Obsidian.AppImage --no-sandbox --remote-debugging-port=9223
 *
 * then:
 *
 *   npx tsx recorder/recordObsidian.ts \
 *     --storyboard storyboards/eng-XXXX-obsidian.ts [--narrate] [--voice x]
 *
 * CDP pages cannot use Playwright's recordVideo, so frames are captured in a
 * screenshot loop with real timestamps and assembled via the ffmpeg concat
 * demuxer (per-frame durations keep wall-clock timing exact). Captions and
 * Kokoro narration work like recordDemo.ts: scene captions are burned in as
 * subtitles and voiced, and every scene is held at least as long as its
 * narration clip.
 *
 * Flags:
 *   --storyboard <file>   Required. Storyboard module (recordDemo Scene shape;
 *                         supported actions: click, type, fill, press, pause,
 *                         wait_for, js, screenshot).
 *   --cdp <url>           CDP endpoint (default http://127.0.0.1:9223).
 *   --narrate / --voice   Kokoro narration from scene captions.
 *   --timeout <ms>        Default step timeout (default 45000).
 */
import { spawn } from "node:child_process";
