    .first()
    .fill(email, { timeout });
  await page
    .locator('input[name="password"], input[type="password"]')
    .first()
    .fill(password, { timeout });

  await page
    .locator("button")
    .filter({ hasText: /^(Sign In|Log In)$/i })
    .first()
    .click({ timeout });

  await waitForReadySelector({ page, timeout });
};

