const log = (message: string) => {
  console.log(`[recordObsidian] ${message}`);
};

const parseArgs = (argv: string[]): Map<string, string | boolean> => {
  const args = new Map<string, string | boolean>();
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (!arg.startsWith("--")) continue;
    const key = arg.slice(2);
    const next = argv[i + 1];
    if (next && !next.startsWith("--")) {
      args.set(key, next);
      i += 1;
    } else {
      args.set(key, true);
    }
  }
  return args;
};

const runFfmpeg = (ffmpegArgs: string[]): Promise<void> =>
  new Promise((resolve, reject) => {
    const child = spawn("ffmpeg", ffmpegArgs, { stdio: ["ignore", "ignore", "pipe"] });
    let stderr = "";
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
    });
    child.once("error", reject);
    child.once("exit", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`ffmpeg exited with ${code}:\n${stderr.slice(-2000)}`));
    });
  });

type NarrationClip = { sceneIndex: number; path: string; durationMs: number };

const synthesizeNarration = async ({
  scenes,
  voice,
  outDir,
}: {
  scenes: Scene[];
  voice: string;
  outDir: string;
}): Promise<Map<number, NarrationClip>> => {
  const lines = scenes
    .map((scene, sceneIndex) => ({ sceneIndex, text: scene.caption }))
    .filter((line): line is { sceneIndex: number; text: string } => !!line.text);
  if (!lines.length) return new Map();

  const python =
    process.env.DG_TTS_PYTHON ||
    "/mnt/data/projects/dg-demo-videos/tts/.venv/bin/python";
  const request = JSON.stringify({
    voice,
    speed: 1.0,
    outDir,
    lines: lines.map((line) => ({
      id: `narration-${line.sceneIndex + 1}`,
      text: line.text,
    })),
  });
  const stdout = await new Promise<string>((resolve, reject) => {
    const child = spawn(python, [path.join(__dirname, "narrate.py")], {
      stdio: ["pipe", "pipe", "pipe"],
    });
    let out = "";
    let err = "";
    child.stdout.on("data", (chunk: Buffer) => {
      out += chunk.toString();
    });
    child.stderr.on("data", (chunk: Buffer) => {
      err += chunk.toString();
    });
    child.once("error", reject);
    child.once("exit", (code) => {
      if (code === 0) resolve(out);
      else reject(new Error(`narrate.py exited with ${code}:\n${err.slice(-2000)}`));
    });
    child.stdin.end(request);
  });
  const clips = JSON.parse(stdout) as {
    id: string;
    path: string;
    durationMs: number;
  }[];
  return new Map(
    clips.map((clip) => {
      const sceneIndex = Number(clip.id.replace("narration-", "")) - 1;
      return [sceneIndex, { sceneIndex, path: clip.path, durationMs: clip.durationMs }];
    }),
  );
};

const toSrtTime = (ms: number): string => {
  const clamped = Math.max(0, Math.round(ms));
  const h = Math.floor(clamped / 3600000);
  const m = Math.floor((clamped % 3600000) / 60000);
  const s = Math.floor((clamped % 60000) / 1000);
  const rem = clamped % 1000;
  const pad = (value: number, width: number) => String(value).padStart(width, "0");
  return `${pad(h, 2)}:${pad(m, 2)}:${pad(s, 2)},${pad(rem, 3)}`;
};

