      const frontmatter = cache?.frontmatter || {};
      if (!frontmatter.nodeTypeId) {
        return false;
      }
      if (frontmatter.importedFromRid) {
        return false;
      }
      if (!checking) {
        if (!frontmatter.nodeInstanceId) {
          new Notice("Please sync the node first");
          return true;
        }
        void openPublishGroupPicker({ plugin, file });
      }
      return true;
    },
  });
};

