        {
          text: "complement",
          children: [{ text: complement }],
        },
      ],
    },
  });
  setGlobalSetting([GLOBAL_KEYS.relations, blockUid], {
    label,
    source,
    destination,
    complement,
    ifConditions: [],
  });
  return blockUid;
};
