const getRequiredEnv = (name: string): string => {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required environment variable ${name}`);
  return value;
};

const getCaseId = (): CaseId => {
  const caseId = process.argv.at(-1);
  if (caseId === "SEC-01" || caseId === "SEC-02") return caseId;
  throw new Error(
    "Usage: tsx scripts/validation/runSecRepros.ts SEC-01|SEC-02",
  );
};

const assertLocalTarget = (): string => {
  const target = getRequiredEnv("DG_VALIDATION_LOCAL_URL").replace(/\/$/, "");
  if (target !== EXPECTED_URL) {
    throw new Error(
      `Refusing to run against ${target}. Set DG_VALIDATION_LOCAL_URL=${EXPECTED_URL}.`,
    );
  }
  return target;
};

const getClients = (): { service: Client; target: string } => {
  const target = assertLocalTarget();
  getRequiredEnv("SUPABASE_PUBLISHABLE_KEY");
  const serviceKey = getRequiredEnv("SUPABASE_SERVICE_ROLE_KEY");
  return {
    target,
    service: createClient<Database, "public">(target, serviceKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    }),
  };
};

const assertNoError = ({
  error,
  context,
}: {
  error: unknown;
  context: string;
}): void => {
  if (error) throw new Error(`${context}: ${String(error)}`);
};

const getRunUser = ({
  role,
  users,
}: {
  role: string;
  users: RunUser[];
}): RunUser => {
  const user = users.find((candidate) => candidate.role === role);
  if (!user) throw new Error(`Missing ${role} fixture user`);
  return user;
};

const getErrorMessage = (error: { message?: string } | null): string | null =>
  error?.message ?? null;

const createUser = async ({
  service,
  runId,
  role,
}: {
