import type { Database } from "@repo/database/dbTypes";

type CaseId = "SEC-01" | "SEC-02";
type RunRecord = {
  candidate: string;
  caseId: CaseId;
  cleanup: { attempted: boolean; verified: boolean; errors: string[] };
  createdAt: string;
  observation: Record<string, unknown>;
  runId: string;
  target: string;
};

type Client = SupabaseClient<Database, "public">;
type RunUser = { email: string; id: string; role: string };

const EXPECTED_URL = "http://127.0.0.1:56321";
const CANDIDATE = "b3796a70b526541014c92a40f685389060b862fe";
const REDACTED = "validation-only-password";

const getRequiredEnv = (name: string): string => {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required environment variable ${name}`);
  return value;
};

const getCaseId = (): CaseId => {
  const caseId = process.argv.at(-1);
  if (caseId === "SEC-01" || caseId === "SEC-02") return caseId;
  throw new Error(
    "Usage: tsx scripts/validation/runSecRepros.ts SEC-01|SEC-02",
  );
};

const assertLocalTarget = (): string => {
  const target = getRequiredEnv("DG_VALIDATION_LOCAL_URL").replace(/\/$/, "");
  if (target !== EXPECTED_URL) {
    throw new Error(
      `Refusing to run against ${target}. Set DG_VALIDATION_LOCAL_URL=${EXPECTED_URL}.`,
    );
  }
  return target;
};

const getClients = (): { service: Client; target: string } => {
  const target = assertLocalTarget();
  getRequiredEnv("SUPABASE_PUBLISHABLE_KEY");
  const serviceKey = getRequiredEnv("SUPABASE_SERVICE_ROLE_KEY");
  return {
    target,
    service: createClient<Database, "public">(target, serviceKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    }),
  };
};

const assertNoError = ({
  error,
  context,
}: {
  error: unknown;
  context: string;
}): void => {
  if (error) throw new Error(`${context}: ${String(error)}`);
};

const getRunUser = ({
  role,
  users,
}: {
  role: string;
  users: RunUser[];
}): RunUser => {
  const user = users.find((candidate) => candidate.role === role);
  if (!user) throw new Error(`Missing ${role} fixture user`);
  return user;
};

const getErrorMessage = (error: { message?: string } | null): string | null =>
  error?.message ?? null;

const createUser = async ({
  service,
  runId,
  role,
}: {
  service: Client;
  runId: string;
  role: string;
}): Promise<RunUser> => {
  const email = `${runId}-${role}@validation.local`;
  const response = await service.auth.admin.createUser({
    email,
    password: REDACTED,
    email_confirm: true,
  });
  assertNoError({ error: response.error, context: `create ${role} user` });
  const id = response.data.user?.id;
  if (!id) throw new Error(`create ${role} user returned no user`);
  return { email, id, role };
};

const signIn = async ({
  email,
  target,
}: {
  email: string;
  target: string;
}): Promise<Client> => {
  const client = createClient<Database, "public">(
    target,
    getRequiredEnv("SUPABASE_PUBLISHABLE_KEY"),
    { auth: { autoRefreshToken: false, persistSession: false } },
  );
  const response = await client.auth.signInWithPassword({
    email,
    password: REDACTED,
  });
  assertNoError({ error: response.error, context: `sign in ${email}` });
  return client;
};

const createSpace = async ({
  service,
  runId,
  suffix,
}: {
  service: Client;
  runId: string;
  suffix: string;
}): Promise<number> => {
  const response = await service
    .from("Space")
    .insert({
      name: `${runId} ${suffix}`,
      platform: "Roam",
      url: `https://validation.local/${runId}/${suffix}`,
    })
    .select("id")
    .single();
  assertNoError({ error: response.error, context: `create ${suffix} space` });
  if (response.data?.id === undefined)
    throw new Error(`create ${suffix} space returned no id`);
  return response.data.id;
};

const createPlatformAccount = async ({
  service,
  userId,
  runId,
  role,
}: {
  service: Client;
  userId: string;
  runId: string;
  role: string;
}): Promise<string> => {
  const localId = `${runId}-${role}`;
  const response = await service.from("PlatformAccount").insert({
    account_local_id: localId,
    dg_account: userId,
    name: `${runId} ${role}`,
    platform: "Roam",
  });
  assertNoError({
    error: response.error,
    context: `create ${role} platform account`,
  });
  return localId;
};

