const runSec01 = async ({
  service,
  target,
  runId,
}: {
  service: Client;
  target: string;
  runId: string;
}): Promise<RunRecord> => {
  const users: RunUser[] = [];
  const spaces: number[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  try {
    await Promise.all(
      ["owner", "member", "outsider", "control-candidate"].map(async (role) =>
        users.push(await createUser({ service, runId, role })),
      ),
    );
    const owner = getRunUser({ role: "owner", users });
    const member = getRunUser({ role: "member", users });
    const outsider = getRunUser({ role: "outsider", users });
    const controlCandidate = getRunUser({ role: "control-candidate", users });
    const spaceId = await createSpace({
      service,
      runId,
      suffix: "sec01-target",
    });
    spaces.push(spaceId);
    const sec01Roles = [
      "owner",
      "member",
      "outsider",
      "control-candidate",
    ] as const;
    const localIds = await Promise.all(
      [owner, member, outsider, controlCandidate].map(async (user, index) =>
        createPlatformAccount({
          service,
          userId: user.id,
          runId,
          role: sec01Roles[index]!,
        }),
      ),
    );
    await Promise.all([
      grantSpaceAccess({ service, accountId: owner.id, spaceId }),
      grantSpaceAccess({ service, accountId: member.id, spaceId }),
    ]);
    const outsiderClient = await signIn({ email: outsider.email, target });
    const before = await getSpaceGrant({
      service,
      accountId: outsider.id,
      spaceId,
    });
    assert.equal(
      before,
      null,
      "outsider unexpectedly had target-space access before the attempt",
    );
    const outsiderAttempt = await outsiderClient.rpc(
      "upsert_account_in_space",
      {
        local_account: {
          account_local_id: localIds[2]!,
          email: null,
          email_trusted: null,
          name: `${runId} outsider`,
          permissions: "editor",
          space_editor: null,
        },
        space_id_: spaceId,
      },
    );
    const after = await getSpaceGrant({
      service,
      accountId: outsider.id,
      spaceId,
    });
    const memberClient = await signIn({ email: member.email, target });
    const permittedControl = await memberClient.rpc("upsert_account_in_space", {
      local_account: {
        account_local_id: localIds[3]!,
        email: null,
        email_trusted: null,
        name: `${runId} control candidate`,
        permissions: "editor",
        space_editor: null,
      },
      space_id_: spaceId,
    });
    const permittedGrant = await getSpaceGrant({
      service,
      accountId: controlCandidate.id,
      spaceId,
    });
    observation = {
      outsiderAttempt: {
        error: getErrorMessage(outsiderAttempt.error),
        returnedAccountId: outsiderAttempt.data ?? null,
      },
      outsiderGrantAfter: after,
      permittedMemberControl: {
        error: getErrorMessage(permittedControl.error),
        grant: permittedGrant,
      },
      hypothesisReproduced: outsiderAttempt.error === null && after !== null,
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds: [],
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return {
    candidate: CANDIDATE,
    caseId: "SEC-01",
    cleanup,
    createdAt: new Date().toISOString(),
    observation,
    runId,
    target,
  };
};

const runSec02 = async ({
  service,
  target,
  runId,
}: {
  service: Client;
  target: string;
  runId: string;
}): Promise<RunRecord> => {
  const users: RunUser[] = [];
  const spaces: number[] = [];
  const groupIds: string[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  try {
    const roles = [
      "outsider",
      "protected-group",
      "positive-group",
      "positive-admin",
      "positive-member",
      "former-member",
      "rejoin-group",
    ];
    await Promise.all(
      roles.map(async (role) => {
        users.push(await createUser({ service, runId, role }));
      }),
    );
    const outsider = getRunUser({ role: "outsider", users });
    const protectedGroup = getRunUser({ role: "protected-group", users });
    const positiveGroup = getRunUser({ role: "positive-group", users });
    const positiveAdmin = getRunUser({ role: "positive-admin", users });
    const positiveMember = getRunUser({ role: "positive-member", users });
    const formerMember = getRunUser({ role: "former-member", users });
    const rejoinGroup = getRunUser({ role: "rejoin-group", users });
    groupIds.push(protectedGroup.id, positiveGroup.id, rejoinGroup.id);
    const protectedSpaceId = await createSpace({
      service,
      runId,
      suffix: "sec02-protected",
    });
    spaces.push(protectedSpaceId);
    await grantSpaceAccess({
      service,
      accountId: protectedGroup.id,
      spaceId: protectedSpaceId,
    });
    const outsiderClient = await signIn({ email: outsider.email, target });
    const freshAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: protectedGroup.id,
      member_id: outsider.id,
    });
    const inheritedSpaceRead = await outsiderClient
      .from("Space")
      .select("id")
      .eq("id", protectedSpaceId)
      .maybeSingle();
    const seedAdmin = await service.from("group_membership").insert({
      admin: true,
      group_id: positiveGroup.id,
      member_id: positiveAdmin.id,
    });
    assertNoError({
      error: seedAdmin.error,
      context: "seed positive-control group admin",
    });
    const positiveAdminClient = await signIn({
      email: positiveAdmin.email,
      target,
    });
    const permittedControl = await positiveAdminClient
      .from("group_membership")
      .insert({
        admin: false,
        group_id: positiveGroup.id,
        member_id: positiveMember.id,
      });
    const seedFormerMember = await service.from("group_membership").insert({
      admin: false,
      group_id: rejoinGroup.id,
      member_id: formerMember.id,
    });
    assertNoError({
      error: seedFormerMember.error,
      context: "seed former member",
    });
    const removeFormerMember = await service
      .from("group_membership")
      .delete()
      .eq("group_id", rejoinGroup.id)
      .eq("member_id", formerMember.id);
    assertNoError({
      error: removeFormerMember.error,
      context: "empty rejoin group",
    });
    const rejoinAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: rejoinGroup.id,
      member_id: outsider.id,
    });
    observation = {
      freshAttempt: { error: getErrorMessage(freshAttempt.error) },
      inheritedProtectedSpaceRead: {
        error: getErrorMessage(inheritedSpaceRead.error),
        visible: inheritedSpaceRead.data !== null,
      },
      permittedAdminControl: { error: getErrorMessage(permittedControl.error) },
      emptyGroupRejoinAttempt: { error: getErrorMessage(rejoinAttempt.error) },
      hypothesisReproduced:
        freshAttempt.error === null &&
        inheritedSpaceRead.data !== null &&
        rejoinAttempt.error === null,
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds,
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return {
    candidate: CANDIDATE,
    caseId: "SEC-02",
    cleanup,
    createdAt: new Date().toISOString(),
    observation,
    runId,
    target,
  };
};

const writeRecord = async (record: RunRecord): Promise<void> => {
  const outputPath = getRequiredEnv("DG_VALIDATION_RESULT_PATH");
  const resultsRoot = resolve(
    "/mnt/data/projects/dg-validation-eng-1883/runs/",
  );
  if (!resolve(outputPath).startsWith(`${resultsRoot}/`)) {
    throw new Error(`Refusing to write result outside ${resultsRoot}`);
  }
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, `${JSON.stringify(record, null, 2)}\n`, {
    mode: 0o600,
  });
};

const main = async (): Promise<void> => {
  const caseId = getCaseId();
  const { service, target } = getClients();
  const runId = `eng1883-${caseId.toLowerCase()}-${randomUUID().slice(0, 8)}`;
  const record =
    caseId === "SEC-01"
      ? await runSec01({ service, target, runId })
      : await runSec02({ service, target, runId });
  await writeRecord(record);
  if (!record.cleanup.verified) process.exitCode = 2;
  else if (record.observation.hypothesisReproduced !== true)
    process.exitCode = 1;
};

void main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 2;
});

