  const { data: dbNodeTypeSchemas, error: nsError } = await client
    .from("my_concepts")
    .select()
    .in("id", [...nodeTypeSchemaIds]);
  if (nsError) throw nsError;
  if (!dbNodeTypeSchemas) throw new Error("Missing relation type schemas");
  const authorIds = [
    ...dbRelations,
