-- The first statement is expected to raise 42804, matching SEC-01.

SELECT COALESCE(
  NULL::public."SpaceAccessPermissions",
  CASE
    WHEN true THEN 'editor'
    WHEN false THEN 'reader'
  END
);

-- This is the same expression after explicitly making every CASE branch enum
-- typed. It demonstrates the function-body type boundary; it is not a schema
-- or function change.
SELECT pg_typeof(
  COALESCE(
    NULL::public."SpaceAccessPermissions",
    CASE
      WHEN true THEN 'editor'::public."SpaceAccessPermissions"
      WHEN false THEN 'reader'::public."SpaceAccessPermissions"
    END
  )
);

